WITH enriched AS (SELECT *, AVG(amount) OVER (ORDER BY paid_at, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS amount_avg_6, RANK() OVER w_hist AS amount_rank, AVG(amount) OVER (ORDER BY amount, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS amount_avg_6_2 FROM payments WHERE order_id IN (8, 23, 36, 37) WINDOW w_hist AS (ORDER BY amount DESC NULLS LAST)) SELECT id, order_id, amount, paid_at, status, amount_avg_6, amount_rank, CASE WHEN status RLIKE '^(FAILED|SUCCESS)$' THEN 'GROUP_B' WHEN status RLIKE '^(REFUNDED)$' THEN 'EXTENDED' ELSE 'GROUP_A' END AS status_zone FROM enriched ORDER BY status DESC NULLS LAST, paid_at
